import io
from rich.console import Console
from rich.file_proxy import FileProxy

class NoIsattyFile:
    def write(self, s):
        pass
    def fileno(self):
        return 1

def test_isatty_with_custom():
    console = Console()
    file = NoIsattyFile()
    proxy = FileProxy(console, file)
    try:
        print(f"CustomFile has isatty: {hasattr(file, 'isatty')}")
        print(f"Proxy has isatty: {hasattr(proxy, 'isatty')}")
        print(f"Proxy isatty value: {proxy.isatty()}")
    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    test_isatty_with_custom()

